import {analyzeVWAP,calculateDCF,optionComparison,generateOptionPaths,generateTradeTape,DCF_DEFAULTS,OPTION_DEFAULTS} from './models.mjs';
import {esc,fmt,pct,lineChart,barChart,legend,table,metric,timeLabel,figure,colours} from './render.mjs';
export const TAPE=generateTradeTape();
export function vwapResult(inputs={startMinute:570,endMinute:960,side:'buy',executionPrice:103}) {
 const r=analyzeVWAP(TAPE,inputs);
 const series=[{name:'Trade price',color:'#486b9a',width:1.5,points:r.chart.map(p=>({x:p.minute,y:p.price}))},{name:'Cumulative VWAP',color:colours[0],width:3,dash:'7 3',points:r.chart.filter(p=>p.cumulativeVWAP!==null).map(p=>({x:p.minute,y:p.cumulativeVWAP}))}];
 const charts=r.count?figure('01','Price and cumulative VWAP',legend(series)+lineChart({series,title:'Synthetic trade prices and cumulative volume-weighted average price',xLabel:'Illustrative exchange-local time',yLabel:'Price · CAD',xFormat:timeLabel,yFormat:v=>fmt(v,2)}),'The cumulative calculation resets at the selected window’s start.')+figure('02','Traded volume',barChart({points:r.chart.map(p=>({x:p.minute,y:p.volume})),title:'Synthetic volume by trade, aligned with the price panel',height:140,yLabel:'Units per trade',xFormat:timeLabel}),'The same observations supply both panels. All prices and volumes are synthetic.'):`<div class="chart-empty">${esc(r.message)}</div>`;
 return {result:r,html:`<div class="result-heading"><h2>Execution benchmark</h2><span>${timeLabel(r.startMinute)}–${timeLabel(r.endMinute)} · synthetic session</span></div><div class="metrics">${metric('Window VWAP',r.vwap===null?'—':`$${fmt(r.vwap)}`,'volume-weighted price',true)}${metric('Execution cost',r.executionCostBps===null?'—':`${fmt(r.executionCostBps,1)}`,'basis points · positive is worse')}${metric('Traded volume',fmt(r.volume,0),`${r.count} simulated trades`)}</div>${charts}<p class="note">${r.message?esc(r.message):`For a ${r.side}, ${r.executionCostBps>0?'this execution is above the benchmark cost':r.executionCostBps<0?'this execution is favorable to the benchmark':'this execution matches the benchmark'}. This comparison excludes fees, market impact and order size.`}</p><details><summary>Inspect the selected trade data</summary>${table(['Time','Trade price (CAD)','Units','Cumulative VWAP'],r.chart.map(p=>[p.time,fmt(p.price,2),fmt(p.volume,0),fmt(p.cumulativeVWAP,4)]),{caption:'Selected synthetic observations · start inclusive, end exclusive',tall:true})}</details><div class="downloads"><button type="button" data-download="vwap">Download selected CSV</button><a href="/assets/models.mjs" download="portfolio-models.mjs">Calculation source</a></div>`};
}
function bridge(r){const values=[{label:'Operating EV',start:0,end:r.enterpriseValue,total:true},{label:'Cash',start:r.enterpriseValue,end:r.enterpriseValue+r.inputs.cash},{label:'Debt',start:r.enterpriseValue+r.inputs.cash,end:r.equityValue},{label:'Equity',start:0,end:r.equityValue,total:true}];const top=Math.max(0,...values.flatMap(v=>[v.start,v.end]))*1.12,min=Math.min(0,...values.flatMap(v=>[v.start,v.end]));const y=v=>25+(top-v)/(top-min||1)*190;return `<div class="chart-frame" tabindex="0" role="region" aria-label="Valuation bridge"><svg class="chart" viewBox="0 0 700 255" role="img" aria-label="Enterprise value plus non-operating cash minus debt equals equity value, in CAD millions"><line class="grid-line" x1="40" x2="680" y1="${y(0)}" y2="${y(0)}"/>${values.map((v,i)=>`<rect x="${64+i*158}" y="${y(Math.max(v.start,v.end))}" width="94" height="${Math.max(.6,Math.abs(y(v.start)-y(v.end)))}" fill="${v.total?'#132f40':v.end>=v.start?'#076e67':'#ad582b'}"/><text x="${111+i*158}" y="${y(Math.max(v.start,v.end))-9}" text-anchor="middle">${fmt(v.total?v.end:v.end-v.start,1)}</text><text x="${111+i*158}" y="243" text-anchor="middle">${v.label}</text>${i<3?`<line x1="${158+i*158}" x2="${222+i*158}" y1="${y(v.end)}" y2="${y(v.end)}" stroke="#8a9c98" stroke-dasharray="3 3"/>`:''}`).join('')}</svg>`;}
export function valuationResult(inputs=DCF_DEFAULTS){
 const r=calculateDCF(inputs),growths=[-2,-1,0,1,2].map(i=>inputs.terminalGrowth+i*.005),waccs=[-2,-1,0,1,2].map(i=>inputs.wacc+i*.01);
 const sensitivity=waccs.map(w=>growths.map(g=>{try{return calculateDCF({...inputs,wacc:w,terminalGrowth:g}).valuePerShare}catch{return null}}));
 const finite=sensitivity.flat().filter(Number.isFinite),min=Math.min(...finite),max=Math.max(...finite);
 const heatmap=`<div class="table-scroll" tabindex="0" role="region" aria-label="Value per share sensitivity"><table class="data-table"><caption>Value per diluted share (CAD) · columns: terminal growth; rows: WACC</caption><thead><tr><th scope="col">WACC / g</th>${growths.map(g=>`<th scope="col">${pct(g)}</th>`).join('')}</tr></thead><tbody>${waccs.map((w,i)=>`<tr><th scope="row">${pct(w)}</th>${sensitivity[i].map(v=>`<td style="background:rgba(7,110,103,${v===null?0:.04+.21*(v-min)/(max-min||1)})">${v===null?'—':fmt(v)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
 return {result:r,sensitivity,growths,waccs,html:`<div class="result-heading"><h2>Fictional business · operating DCF</h2><span>CAD millions, except per share</span></div><div class="metrics">${metric('Value per diluted share',`$${fmt(r.valuePerShare)}`,'illustrative equity value',true)}${metric('Enterprise value',`$${fmt(r.enterpriseValue,1)}m`,'operating assets')}${metric('Terminal contribution',pct(r.terminalContribution),'share of enterprise value')}</div>${figure('01','Cash flow through the forecast',barChart({points:r.forecast.map(p=>({x:`Y${p.year}`,y:p.freeCashFlow})),height:210,title:'Five annual forecast free cash flows',yLabel:'FCFF · CAD millions'}),'After-tax operating profit less the reinvestment required for forecast growth.')}${figure('02','From business value to equity value',bridge(r),'Non-operating cash is added; the valuation-date debt claim is subtracted.')}${figure('03','What changes the valuation?',heatmap,'Terminal reinvestment is recalculated for every growth assumption. A dash marks an invalid model combination.')}<p class="note">${pct(r.terminalContribution)} of enterprise value comes from the discounted terminal value. Forecast incremental return on capital is ${pct(inputs.margin*(1-inputs.tax)*inputs.salesToCapital)}; the model switches directly to a ${pct(inputs.terminalReturnOnCapital)} terminal return after Year 5.</p><details><summary>Inspect the forecast and terminal cash flow</summary>${table(['Period','Revenue','EBIT','NOPAT','Reinvestment','FCFF','Present value'],[...r.forecast.map(p=>[`Year ${p.year}`,fmt(p.revenue),fmt(p.ebit),fmt(p.nopat),fmt(p.reinvestment),fmt(p.freeCashFlow),fmt(p.presentValue)]),['Year 6 terminal',fmt(r.terminal.revenue),'—',fmt(r.terminal.nopat),fmt(r.terminal.reinvestment),fmt(r.terminal.freeCashFlow),'—']],{caption:'CAD millions · end-of-year discounting; terminal value at end of Year 5'})}</details><div class="downloads"><button type="button" data-download="forecast">Forecast CSV</button><button type="button" data-download="assumptions">Assumptions JSON</button><a href="/assets/models.mjs" download="portfolio-models.mjs">Calculation source</a></div>`};
}
export function optionsResult(inputs=OPTION_DEFAULTS){
 const r=optionComparison(inputs);const rows=Array.from({length:17},(_,i)=>{const strike=Math.min(100000,Math.max(.01,inputs.spot*(.6+.05*i)));return {strike,...optionComparison({...inputs,strike})}});
 const series=[{name:'Black–Scholes',color:colours[1],dash:'7 4',points:rows.map(p=>({x:p.strike,y:p.blackScholes.price}))},{name:'Merton jumps',color:colours[0],points:rows.map(p=>({x:p.strike,y:p.merton.price}))},{name:'Variance-matched diffusion',color:colours[2],dash:'2 4',points:rows.map(p=>({x:p.strike,y:p.varianceMatched.price}))}];
 const paths=generateOptionPaths(inputs,{steps:64,seed:1976,pairs:1});const paired=[{name:'Diffusion path',color:colours[1],dash:'7 4',points:paths.paths[0].diffusion.map(p=>({x:p.t,y:p.price}))},{name:'Jump path',color:colours[0],points:paths.paths[0].merton.map(p=>({x:p.t,y:p.price}))}];
 return {result:r,rows,paths,html:`<div class="result-heading"><h2>European ${esc(inputs.type)} · chosen pricing assumptions</h2><span>Values per option · currency units</span></div><div class="metrics">${metric('Black–Scholes',fmt(r.blackScholes.price,4),'continuous returns')}${metric('Merton jump diffusion',fmt(r.merton.price,4),`${r.merton.terms} series terms`,true)}${metric('Variance-matched',fmt(r.varianceMatched.price,4),`${pct(r.matchedVolatility,2)} diffusion volatility`)}</div>${figure('01','Option prices across strikes',legend(series)+lineChart({series,title:'European option price against strike for three model assumptions',xLabel:'Strike',yLabel:'Option price',yFormat:v=>fmt(v,1)}),'The dotted diffusion benchmark matches log-return variance, not skewness or tail behavior.')}${figure('02','Continuous motion and discrete jumps',legend(paired)+lineChart({series:paired,title:'A paired simulation of diffusion and jump-diffusion stock prices',xLabel:'Time · years',yLabel:'Underlying price',xFormat:v=>fmt(v,2)}),'One reproducible pair, seed 1976, sharing Brownian increments. Sampled paths are illustrations, not forecasts.')}<p class="note">Merton minus Black–Scholes: <strong>${fmt(r.merton.price-r.blackScholes.price,4)}</strong>. Omitted-series price bound: ${r.merton.priceTailBound.toExponential(2)}. This bound covers truncation, not floating-point or normal-CDF error.</p><details><summary>Inspect model prices and simulated path values</summary>${table(['Strike','Black–Scholes','Merton','Variance-matched'],rows.map(p=>[fmt(p.strike),fmt(p.blackScholes.price,6),fmt(p.merton.price,6),fmt(p.varianceMatched.price,6)]),{caption:'Calculated strike comparison',tall:true})}${table(['Time (years)','Diffusion','Jump diffusion'],paths.paths[0].diffusion.map((p,i)=>[fmt(p.t,4),fmt(p.price,4),fmt(paths.paths[0].merton[i].price,4)]),{caption:'Paired simulated prices · seed 1976',tall:true})}</details><div class="downloads"><button type="button" data-download="options">Price comparison CSV</button><button type="button" data-download="option-inputs">Assumptions JSON</button><a href="/assets/models.mjs" download="portfolio-models.mjs">Calculation source</a></div>`};
}
